    expect(
      await (
        hub as unknown as {
          resolveNextRuntimeCoordinatorHeadWaitingAlarmAtMs(): Promise<
            number | null
          >;
        }
      ).resolveNextRuntimeCoordinatorHeadWaitingAlarmAtMs()
    ).toBe(request.acceptedDispatchSnapshot.deviceWait.deadlineAtMs);
