  it.each([
    "connected",
    "expired_controller_report",
    "unavailable_controller_report",
    "same_service_reconnect",
    "same_service_reconnect_after_hibernation",
  ] as const)("records Wake Stop as cancellation_requested for an eligible active RuntimeCoordinator execution (%s)", async (connection) => {
    const {
      hub,
      recordingPostgres,
      sentFrames,
      socket,
      state,
      storageRecords,
    } = await createHarness({
      agentControllerReportRow: buildRuntimeAgentControllerReportRow({
        expiresAtMs:
          connection === "expired_controller_report"
            ? Date.now() - 60_000
            : undefined,
        reportStatus:
          connection === "unavailable_controller_report"
            ? "unavailable"
            : "ready",
      }),
    });
    const executionToken = await issueDeliveryToken({
      hub,
      sentFrames,
      socket,
      state,
    });
    const session = state.sessionsById.get("daemon-session-1");
    if (!session) {
      throw new Error("Expected live daemon session.");
    }
    session.capabilities = {
      ...session.capabilities,
      localAgentControl: { cancel: true },
    };
    enableLocalAgentInteraction(state);
    await (
      hub as unknown as {
        handleDispatchInteractionRequestFrame: (
          webSocket: WebSocket,
          payload: unknown
        ) => Promise<void>;
      }
    ).handleDispatchInteractionRequestFrame(
      socket,
      buildInteractionRequest(executionToken)
    );

    if (
      connection === "same_service_reconnect" ||
      connection === "same_service_reconnect_after_hibernation"
    ) {
      const lifecycleHub = hub as unknown as {
        handleDispatchLifecycleFrame: (
          webSocket: WebSocket,
          payload: unknown
        ) => Promise<void>;
      };
      await lifecycleHub.handleDispatchLifecycleFrame(
        socket,
        buildLifecycleRequest({
          executionTokenEcho: buildExecutionTokenEcho(executionToken),
          runtimeCoordinatorExecutionId: RUNTIME_COORDINATOR_EXECUTION_ID,
        })
      );
      session.connectionGeneration += 1;
      if (connection === "same_service_reconnect_after_hibernation") {
        state.pendingDispatches.clear();
      }
      await lifecycleHub.handleDispatchLifecycleFrame(
        socket,
        buildLifecycleRequest({
          acknowledgementId: "09ea9be9-3a69-4c95-81ed-0236f56efddd",
          connectionGeneration: session.connectionGeneration,
          executionTokenEcho: buildExecutionTokenEcho(executionToken),
          runtimeCoordinatorExecutionId: RUNTIME_COORDINATOR_EXECUTION_ID,
        })
      );
      expect(sentFrames.at(-1)).toMatchObject({
        code: "daemon.dispatch.lifecycle_acknowledged",
        payload: { accepted: true },
      });
    }

    const response = await requestRuntimeCoordinatorWakeStop(hub);

    expect(response.status).toBe(200);
    await expect(response.json()).resolves.toMatchObject({
      ok: true,
      runtimeCoordinatorExecutionId: RUNTIME_COORDINATOR_EXECUTION_ID,
      status: "cancellation_requested",
      targetProfileId: TARGET_AGENT_PROFILE_ID,
      cancellationState: {
        reasonCode: "runtime_coordinator.wake_stop_delivery_pending",
        status: "delivery_pending",
      },
    });
    expect(sentFrames).toContainEqual(
      expect.objectContaining({
        code: "daemon.dispatch.interaction_response",
        payload: expect.objectContaining({
          interactionId: "interaction-1",
          response: { kind: "cancel" },
        }),
      })
    );
    expect(sentFrames).toContainEqual(
      expect.objectContaining({
        code: "daemon.local_agent_control.cancel",
        payload: {
          requestId: `wake-stop:${RUNTIME_COORDINATOR_EXECUTION_ID}`,
          payload: {
            runtimeCoordinatorExecutionId: RUNTIME_COORDINATOR_EXECUTION_ID,
            target: {
              by: "task",
              taskId: "task-1",
            },
          },
        },
      })
    );
    expect(
      await recordingPostgres.projectionRows.get(
        RUNTIME_COORDINATOR_EXECUTION_ID
      )
    ).toMatchObject({
      status: "cancellation_requested",
      terminal_outcome_json: null,
    });
    expect(findRuntimeCoordinatorRunCommandState(storageRecords)).toMatchObject(
      {
        lastCommandReasonCode: "runtime_coordinator.wake_stop_delivery_pending",
        pendingInteraction: {
          response: { kind: "cancel" },
        },
        runtimeCoordinatorExecutionId: RUNTIME_COORDINATOR_EXECUTION_ID,
      }
    );
    expect([
      ...(await recordingPostgres.interactionInboxRows.values()),
    ]).toEqual([expect.objectContaining({ resolution_status: "resolved" })]);
    const requestedEvents = getRuntimeCoordinatorEventCalls(
      recordingPostgres.calls
    ).filter((call) => call.params[2] === "cancellation_requested");
    expect(requestedEvents).toHaveLength(1);
    expect(requestedEvents[0]?.params[3]).toBe("cancellation_requested");
    expect(JSON.parse(String(requestedEvents[0]?.params[7]))).toMatchObject({
      controlMode: "cancel",
      reliability: "native_cancel",
      source: "space_wake_stop",
    });
    const deliveryEvents = getRuntimeCoordinatorEventCalls(
      recordingPostgres.calls
    ).filter((call) => call.params[2] === "cancellation_delivery_accepted");
    expect(deliveryEvents).toHaveLength(1);
    expect(deliveryEvents[0]?.params[3]).toBe("cancellation_requested");
    expect(JSON.parse(String(deliveryEvents[0]?.params[7]))).toMatchObject({
      controlMode: "cancel",
      requestId: `wake-stop:${RUNTIME_COORDINATOR_EXECUTION_ID}`,
      reliability: "native_cancel",
    });

    const repeatResponse = await requestRuntimeCoordinatorWakeStop(hub);

    expect(repeatResponse.status).toBe(200);
    await expect(repeatResponse.json()).resolves.toMatchObject({
      ok: true,
      runtimeCoordinatorExecutionId: RUNTIME_COORDINATOR_EXECUTION_ID,
      status: "cancellation_requested",
      cancellationState: {
        status: "delivery_pending",
      },
    });
    expect(
      getRuntimeCoordinatorEventCalls(recordingPostgres.calls).filter(
        (call) => call.params[2] === "cancellation_requested"
      )
    ).toHaveLength(1);
  });

  it.each([
    ["replaced_socket", "daemon.session.not_found"],
    ["stale_generation", "daemon.session.connection_replaced"],
    ["different_owner", "daemon.session.not_found"],
    ["stale_lease", "daemon.session.stale_lease"],
    ["different_device", "daemon.session.connection_replaced"],
    ["different_lane", "daemon.session.connection_replaced"],
    ["missing_profile", "daemon.session.not_found"],
  ] as const)("does not move Wake Stop control to an unowned reconnect (%s)", async (mismatch, reasonCode) => {
    const harness = await createHarness({
      agentControllerReportRow: buildRuntimeAgentControllerReportRow(),
    });
    const { hub, sentFrames, socket, state, storageRecords } = harness;
    const token = await issueDeliveryToken(harness);
    const session = state.sessionsById.get("daemon-session-1");
    const lease = state.profileLeasesByProfileId.get(TARGET_AGENT_PROFILE_ID);
    if (!(session && lease)) {
      throw new Error("Expected owned Service route.");
    }
    session.capabilities.localAgentControl = { cancel: true };
    const lifecycleHub = hub as unknown as {
      handleDispatchLifecycleFrame: (
        webSocket: WebSocket,
        payload: unknown
      ) => Promise<void>;
    };
    await lifecycleHub.handleDispatchLifecycleFrame(
      socket,
      buildLifecycleRequest({
        executionTokenEcho: buildExecutionTokenEcho(token),
        runtimeCoordinatorExecutionId: RUNTIME_COORDINATOR_EXECUTION_ID,
      })
    );
    const before = findRuntimeCoordinatorRunCommandState(storageRecords);
    session.connectionGeneration += 1;
    state.pendingDispatches.clear();
    switch (mismatch) {
      case "replaced_socket":
        // biome-ignore lint/correctness/noUndeclaredVariables: Cloudflare Workers provides this native constructor.
        session.socket = new WebSocketPair()[0];
        break;
      case "different_owner":
        session.ownerUserId = "different-owner";
        break;
      case "stale_lease":
        lease.leaseEpoch += 1;
        break;
      case "different_device":
        session.deviceId = "different-device";
        break;
      case "different_lane":
        session.lane = "canary";
        break;
      case "missing_profile":
        session.profileIds.delete(TARGET_AGENT_PROFILE_ID);
        break;
      default:
        break;
    }
    sentFrames.length = 0;

    await lifecycleHub.handleDispatchLifecycleFrame(
      socket,
      buildLifecycleRequest({
        acknowledgementId: "09ea9be9-3a69-4c95-81ed-0236f56efddd",
        connectionGeneration:
          mismatch === "stale_generation" ? 1 : session.connectionGeneration,
        executionTokenEcho: buildExecutionTokenEcho(token),
        lifecycleAtMs: 1_700_000_000_200,
        runtimeCoordinatorExecutionId: RUNTIME_COORDINATOR_EXECUTION_ID,
      })
    );

    expect(sentFrames).toContainEqual(
      expect.objectContaining({
        code: "daemon.dispatch.lifecycle_acknowledged",
        payload: expect.objectContaining({ accepted: false, reasonCode }),
      })
    );
    expect(findRuntimeCoordinatorRunCommandState(storageRecords)).toEqual(
      before
    );
    const stop = await requestRuntimeCoordinatorWakeStop(hub);
    await expect(stop.json()).resolves.toMatchObject({ ok: false });
    expect(
      sentFrames.some(
        (frame) =>
          (frame as { code?: string }).code ===
          "daemon.local_agent_control.cancel"
      )
    ).toBe(false);
  });

  it("keeps the Wake Stop fence when a repeated delivery would otherwise fail to send", async () => {
    let releaseControllerReport: (() => void) | undefined;
    const controllerReportGate = new Promise<void>((resolve) => {
      releaseControllerReport = resolve;
    });
    let markControllerReportReadStarted: (() => void) | undefined;
    const controllerReportReadStarted = new Promise<void>((resolve) => {
      markControllerReportReadStarted = resolve;
    });
    const { hub, sentFrames, socket, state, storageRecords } =
      await createHarness({
        agentControllerReportReadGate: controllerReportGate,
        agentControllerReportRow: buildRuntimeAgentControllerReportRow(),
        onAgentControllerReportRead: () => markControllerReportReadStarted?.(),
      });
    await issueDeliveryToken({ hub, sentFrames, socket, state });
    enableWakeStopControl(state, "cancel");
    const stopResponsePromise = requestRuntimeCoordinatorWakeStop(hub);
    await controllerReportReadStarted;

    state.pendingDispatches.clear();
    const socketSend = vi.mocked(socket.send);
    const sendCountBeforeRepeatedDelivery = socketSend.mock.calls.length;
    socketSend.mockImplementation((message) => {
      if (typeof message !== "string") {
        throw new Error("Expected a serialized runtime transport frame.");
      }
      const frame = JSON.parse(message) as { code?: unknown };
      if (frame.code === "daemon.dispatch.deliver") {
        throw new Error("test repeated delivery send failure");
      }
      sentFrames.push(frame);
    });
    const repeatedDeliveryResponse = await (
      hub as unknown as {
        handleDeliverDispatchRequest: (request: Request) => Promise<Response>;
      }
    ).handleDeliverDispatchRequest(
      new Request("https://runtime-transport.test/deliver-dispatch", {
        body: JSON.stringify(buildDeliverRequest()),
        method: "POST",
      })
    );

    expect(repeatedDeliveryResponse.status).toBe(409);
    await expect(repeatedDeliveryResponse.json()).resolves.toMatchObject({
      accepted: false,
      reasonCode: "runtime_coordinator.pre_agent_stop_requested",
      status: "rejected",
    });
    expect(socketSend).toHaveBeenCalledTimes(sendCountBeforeRepeatedDelivery);
    expect(findRuntimeCoordinatorRunCommandState(storageRecords)).toMatchObject(
      {
        lastCommandReasonCode: "runtime_coordinator.wake_stop_requested",
        runtimeCoordinatorExecutionId: RUNTIME_COORDINATOR_EXECUTION_ID,
      }
    );
    expect(
      findRuntimeCoordinatorHeadLifecycleRecord(storageRecords)
    ).toMatchObject({
      runtimeCoordinatorExecutionId: RUNTIME_COORDINATOR_EXECUTION_ID,
      status: "execution_linked",
    });

    releaseControllerReport?.();
    const stopResponse = await stopResponsePromise;
    expect(stopResponse.status).toBe(200);
    await expect(stopResponse.json()).resolves.toMatchObject({
      ok: true,
      status: "cancellation_requested",
    });
  });

