  it("persists, privacy-projects, responds to, and acknowledges a Local Agent interaction", async () => {
    const { hub, sentFrames, socket, state } = await createHarness();
    const executionToken = await issueDeliveryToken({
      hub,
      sentFrames,
      socket,
      state,
    });
    enableLocalAgentInteraction(state);
    sentFrames.length = 0;

    const requestReceivedAfterMs = Date.now();
    await (
      hub as unknown as {
        handleDispatchInteractionRequestFrame: (
          webSocket: WebSocket,
          payload: unknown
        ) => Promise<void>;
      }
    ).handleDispatchInteractionRequestFrame(
      socket,
      buildInteractionRequest(executionToken)
    );

    const ownerReadResponse = await fetchRuntimeTransportJson(
      hub,
      "/runtime-coordinator/interaction/read-revision",
      {
        actorOwnerUserId: "owner-1",
        runtimeCoordinatorExecutionId: RUNTIME_COORDINATOR_EXECUTION_ID,
        v: RUNTIME_TRANSPORT_SCHEMA_VERSION,
      }
    );
    const ownerRead = (await ownerReadResponse.json()) as {
      interactionUpdatedAtMs: number | null;
    };
    // The revision is the Core arrival time, not the Service's clock.
    expect(ownerRead.interactionUpdatedAtMs).toBeGreaterThanOrEqual(
      requestReceivedAfterMs
    );
    // The frozen read keeps the exact body already-deployed Spaces parse.
    const frozenReadResponse = await fetchRuntimeTransportJson(
      hub,
      "/runtime-coordinator/interaction/read",
      {
        actorOwnerUserId: "owner-1",
        runtimeCoordinatorExecutionId: RUNTIME_COORDINATOR_EXECUTION_ID,
        v: RUNTIME_TRANSPORT_SCHEMA_VERSION,
      }
    );
    const frozenRead = (await frozenReadResponse.json()) as Record<
      string,
      unknown
    >;
    expect(Object.keys(frozenRead)).toEqual(["pendingInteraction"]);
    expect(ownerRead).toMatchObject({
      pendingInteraction: {
        canRespond: true,
        interactionId: "interaction-1",
        kind: "permission",
        request: {
          kind: "permission",
          title: "Allow this command?",
        },
      },
    });

    const otherMemberReadResponse = await fetchRuntimeTransportJson(
      hub,
      "/runtime-coordinator/interaction/read",
      {
        actorOwnerUserId: "other-space-member",
        runtimeCoordinatorExecutionId: RUNTIME_COORDINATOR_EXECUTION_ID,
        v: RUNTIME_TRANSPORT_SCHEMA_VERSION,
      }
    );
    await expect(otherMemberReadResponse.json()).resolves.toMatchObject({
      pendingInteraction: {
        canRespond: false,
        interactionId: "interaction-1",
        kind: "permission",
        request: null,
      },
    });

    const respondResponse = await fetchRuntimeTransportJson(
      hub,
      "/runtime-coordinator/interaction/respond",
      {
        actorOwnerUserId: "owner-1",
        interactionId: "interaction-1",
        response: {
          kind: "permission",
          optionId: "allow-once",
        },
        runtimeCoordinatorExecutionId: RUNTIME_COORDINATOR_EXECUTION_ID,
        v: RUNTIME_TRANSPORT_SCHEMA_VERSION,
      }
    );
    const respondReceipt = (await respondResponse.json()) as {
      respondedAtMs: number;
    };
    expect(respondReceipt).toMatchObject({
      ok: true,
      status: "accepted",
    });
    const answeredRead = await fetchRuntimeTransportJson(
      hub,
      "/runtime-coordinator/interaction/read-revision",
      {
        actorOwnerUserId: "owner-1",
        runtimeCoordinatorExecutionId: RUNTIME_COORDINATOR_EXECUTION_ID,
        v: RUNTIME_TRANSPORT_SCHEMA_VERSION,
      }
    );
    // The answer advances the revision so the cleared request outranks a
    // copy that still shows it.
    await expect(answeredRead.json()).resolves.toEqual({
      interactionUpdatedAtMs: respondReceipt.respondedAtMs,
      pendingInteraction: null,
    });
    expect(respondReceipt.respondedAtMs).toBeGreaterThanOrEqual(
      ownerRead.interactionUpdatedAtMs ?? Number.POSITIVE_INFINITY
    );
    expect(sentFrames).toContainEqual(
      expect.objectContaining({
        code: "daemon.dispatch.interaction_response",
        payload: expect.objectContaining({
          interactionId: "interaction-1",
          response: {
            kind: "permission",
            optionId: "allow-once",
          },
        }),
      })
    );

    await (
      hub as unknown as {
        handleDispatchInteractionDeliveredFrame: (
          webSocket: WebSocket,
          payload: unknown
        ) => Promise<void>;
      }
    ).handleDispatchInteractionDeliveredFrame(
      socket,
      buildInteractionDeliveredRequest(executionToken)
    );
    const commandState = await (
      hub as unknown as {
        readRuntimeCoordinatorRunCommandState: (
          runtimeCoordinatorExecutionId: string
        ) => Promise<{ pendingInteraction?: unknown } | null>;
      }
    ).readRuntimeCoordinatorRunCommandState(RUNTIME_COORDINATOR_EXECUTION_ID);
    expect(commandState?.pendingInteraction).toBeNull();
    // A lost HTTP receipt remains retryable after the Agent acknowledged delivery.
    for (const [optionId, expected] of [
      ["allow-once", { ok: true, status: "already_resolved" }],
      ["deny", { ok: false, status: "response_invalid" }],
    ] as const) {
      const retry = await fetchRuntimeTransportJson(
        hub,
        "/runtime-coordinator/interaction/respond",
        {
          actorOwnerUserId: "owner-1",
          interactionId: "interaction-1",
          response: { kind: "permission", optionId },
          runtimeCoordinatorExecutionId: RUNTIME_COORDINATOR_EXECUTION_ID,
          v: RUNTIME_TRANSPORT_SCHEMA_VERSION,
        }
      );
      await expect(retry.json()).resolves.toMatchObject(expected);
    }
    sentFrames.length = 0;
    await (
      hub as unknown as {
        handleDispatchInteractionRequestFrame: (
          socket: WebSocket,
          payload: unknown
        ) => Promise<void>;
      }
    ).handleDispatchInteractionRequestFrame(
      socket,
      buildInteractionRequest(executionToken)
    );
    const replayRead = await fetchRuntimeTransportJson(
      hub,
      "/runtime-coordinator/interaction/read-revision",
      {
        actorOwnerUserId: "owner-1",
        runtimeCoordinatorExecutionId: RUNTIME_COORDINATOR_EXECUTION_ID,
        v: RUNTIME_TRANSPORT_SCHEMA_VERSION,
      }
    );
    await expect(replayRead.json()).resolves.toEqual({
      interactionUpdatedAtMs: respondReceipt.respondedAtMs,
      pendingInteraction: null,
    });
  });

